function isPossibleToSplit(nums) {
  // Search every way to place each element into one of the two halves.
  const half = nums.length / 2;
  const first = [], second = [];
  const place = (i) => {
    if (i === nums.length) return true;
    for (const part of [first, second]) {
      if (part.length < half && !part.includes(nums[i])) {
        part.push(nums[i]);
        if (place(i + 1)) return true;
        part.pop();
      }
    }
    return false;
  };
  return place(0);
}

