function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  if (size === 'small') {
    const n = 2 * int(1, 6);
    const top = int(1, 7);
    return [Array.from({ length: n }, () => int(1, top))];
  }
  const n = 2 * int(45, 50);
  const mode = int(0, 2);
  if (mode === 0) return [Array.from({ length: n }, () => int(1, 100))];
  // Use each value at most twice, then maybe give one value a third copy.
  const pool = [];
  for (let v = 1; v <= 100; v++) pool.push(v, v);
  for (let i = pool.length - 1; i > 0; i--) { const j = int(0, i); [pool[i], pool[j]] = [pool[j], pool[i]]; }
  const nums = pool.slice(0, n);
  if (mode === 2) {
    const value = nums[int(0, n - 1)];
    const others = nums.map((v, i) => i).filter(i => nums[i] !== value);
    for (let k = nums.filter(v => v === value).length; k < 3; k++) {
      const pick = int(0, others.length - 1);
      nums[others[pick]] = value;
      others.splice(pick, 1);
    }
  }
  return [nums];
}
